<?php
require __DIR__.'/config.php';
$id=(int)($_GET['id']??0);
$stmt=db()->prepare("SELECT * FROM trips WHERE id=? AND status='published'"); $stmt->execute([$id]); $trip=$stmt->fetch();
if(!$trip){http_response_code(404);exit('Trip not found. <a href="index.php">Back</a>');}
$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$message=trim($_POST['message']??'');if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&$message){$s=db()->prepare('INSERT INTO inquiries(trip_id,full_name,email,message) VALUES(?,?,?,?)');$s->execute([$id,$name,$email,$message]);$msg='Your inquiry has been sent.';}else $msg='Please fill in all fields correctly.';}
?>
